import {Renderer as RebuildRenderer} from './rebuild-renderer.js';
import {BUILDINGS} from './data.js';
export class Renderer extends RebuildRenderer{
 drawObject(o,e){if(['echoEvent','echoCache','echoDecor'].includes(o.type)){this.shadow(o.x,o.y,20);this.sprite(o.icon||55,o.x,o.y,o.type==='echoDecor'?42:48,48);if(o.type==='echoEvent'){const c=this.ctx;c.save();c.strokeStyle='#f0cf87';c.lineWidth=2;c.setLineDash([5,4]);c.beginPath();c.ellipse(o.x,o.y+3,31,15,0,0,Math.PI*2);c.stroke();c.restore();this.badge(String(e.event(o.eventId).n).padStart(2,'0')+' · '+e.event(o.eventId).name,o.x,o.y-70,'#f1d699');}else this.text(o.name,o.x,o.y-64,'#d5dfba',12);return;}return super.drawObject(o,e);}
 drawFarm(e){super.drawFarm(e);const c=this.ctx,mode=e.v.overlay;if(mode==='events')for(const p of e.s.plots)if(p.rebuildNew&&(e.v.records.drought?.status==='active'||e.v.benefits.secondreport)){c.save();c.strokeStyle='#f0cf87';c.setLineDash([3,3]);c.strokeRect(p.x-20,p.y-20,40,40);this.text('事件田',p.x,p.y-27,'#f0cf87',10);c.restore();}if(mode!=='none'&&mode!=='events')for(const p of e.s.plots){let text,color;if(mode==='water'){text=e.plotWatered(p)?'水✓':'水×';color=e.plotWatered(p)?'#b7e0d3':'#f3c297';}else if(mode==='soil'){text='肥'+Math.round(p.fertility);color=p.fertility>=45?'#c5dc9f':'#efbb96';}else{const safe=e.s.buildings.some(b=>b.type==='greenhouse'&&b.hp>0&&Math.hypot(b.x-p.x,b.y-p.y)<220);text=safe?'棚✓':['酸雨','暴雨'].includes(e.s.weather)?'险!':'晴✓';color=safe?'#b7dfb1':'#efd39e';}c.fillStyle='#18291de8';c.fillRect(p.x-18,p.y-39,36,15);this.text(text,p.x,p.y-26,color,10);}}
 drawEnemy(z,e){super.drawEnemy(z,e);if(z.echoEvent&&!z.dead)this.text(z.echoWeak?'迟钝弱点':'事件目标',z.x,z.y-88,z.echoWeak?'#bedcac':'#f0c895',11);}
 draw(e,mouse,dt=.016){super.draw(e,mouse,dt);if(e.buildMode&&!e.paused){const c=this.ctx,p=this.worldPoint(mouse.x,mouse.y),d=BUILDINGS[e.buildMode],radius={irrigation:300,rain:220,greenhouse:220,tower:320,drone:300}[e.buildMode];if(radius){const screen=this.screenPoint(p.x,p.y);c.save();c.setTransform(this.dpr,0,0,this.dpr,0,0);c.strokeStyle='#b9d896';c.fillStyle='#95b87619';c.setLineDash([6,5]);c.beginPath();c.arc(screen.x,screen.y,radius*this.camera.scale,0,Math.PI*2);c.fill();c.stroke();c.restore();}}
 }
}
